 24	// handleGreedy queues a recursion job for a matched response (greedy strategy: a
 25	// match is enough), if the recursion depth allows. The match has been determined
 26	// by the caller.
 27	func (r *recursionManager) handleGreedy(ctx jobContext, resp ffuf.Response) {
 28		if r.config.RecursionDepth == 0 || ctx.depth < r.config.RecursionDepth {
 29			recUrl := ffuf.RecursionURL(resp.Request.Url)
 30			newJob := QueueJob{Url: recUrl, depth: ctx.depth + 1, req: ffuf.RecursionRequest(r.config, recUrl)}
 31			r.queue.push(newJob)
 32			r.output.Info(fmt.Sprintf("Adding a new job to the queue: %s", recUrl))
 33		} else {
 34			r.output.Warning(fmt.Sprintf("Maximum recursion depth reached. Ignoring: %s", resp.Request.Url))
 35		}
 36	}
